/**
 * Windows resolves `pnpm` to `pnpm.cmd`. `spawn` without a shell does not.
 *
 * `spawn` goes straight to `CreateProcessW`, which launches executable images and appends nothing
 * but `.exe` — `PATHEXT` never enters into it. npm and pnpm both install a global binary as a
 * `.cmd`, a `.ps1` and an extension-less POSIX script, and never an `.exe`, so on Windows every
 * spawn of `pnpm` or `just` in these scripts fails with ENOENT while `docker` and `node`, being
 * real `.exe` files, work fine. That is what made `just doctor` report two installed tools as
 * "not found" (prescribing `brew install just` as the cure), `just up` die at `pnpm install`, and
 * the dev servers exit the instant they were launched.
 *
 * A blanket `shell: true` on Windows is not the fix: Node joins the argv into a single string and
 * sets `windowsVerbatimArguments`, so cmd.exe would split `proxy.mjs`'s `{{range $port,
 * $bindings := .NetworkSettings.Ports}}` and `{{json .NetworkSettings.Networks}}` on their spaces
 * and the shared proxy's published port would start reading as absent — taking the preflight's
 * own port check down with it. So resolve the name the way Windows itself would, and take the
 * cmd.exe detour only for the shims that need one, leaving every real executable's argv exactly
 * as its caller wrote it.
 */

import { spawn } from 'node:child_process';
import { existsSync } from 'node:fs';
import { resolve, win32 } from 'node:path';

/**
 * Since CVE-2024-27980, Node refuses to spawn a `.bat`/`.cmd` without a shell and throws EINVAL
 * *synchronously* — past every `child.on('error')` handler in these scripts, so the naive
 * "append `.cmd` on Windows" fix would crash the recipe rather than report a failure. A shim has
 * to travel as an argument to cmd.exe instead of being spawned itself.
 */
const NEEDS_COMMAND_INTERPRETER = new Set(['.cmd', '.bat']);

// Only ever consulted if a machine has no PATHEXT at all. The real one carries a dozen entries;
// these four are the ones a developer tool ships as.
const DEFAULT_PATHEXT = '.COM;.EXE;.BAT;.CMD';

/**
 * What to hand `spawn` so that `command` actually runs on this platform: `{ command, args }`, plus
 * `windowsVerbatimArguments` when the answer is a trip through cmd.exe. Anything this cannot
 * improve on is returned untouched — off Windows, where `spawn` resolves shims by itself; for a
 * command that names a path (`backend-local.mjs`'s `./gradlew`), which PATH has no say in; and for
 * a name that resolves to nothing, where the caller's existing ENOENT handling is the right answer.
 */
export function resolveCommand(command, args, options = {}) {
  const { platform = process.platform, env = process.env, fileExists = existsSync } = options;
  const searchable = platform === 'win32' && !/[\\/]/.test(command);
  const executable = searchable ? findOnPath(command, env, fileExists) : null;

  if (executable === null) {
    return { command, args };
  } else if (NEEDS_COMMAND_INTERPRETER.has(win32.extname(executable).toLowerCase())) {
    return {
      command: valueOf(env, 'ComSpec') ?? 'cmd.exe',
      args: ['/d', '/s', '/c', commandLine(executable, args)],
      windowsVerbatimArguments: true,
    };
  } else {
    return { command: executable, args };
  }
}

/**
 * `spawn`, with the resolution applied — the one place these scripts should reach for when they
 * mean "run this command name". Injectable through `spawnProcess` the way `compose.mjs`'s
 * `runInherited` is, so a test can watch what was resolved without spawning anything.
 *
 * The child also gets a `PWD` naming the directory it actually runs in. A POSIX shell rewrites
 * `PWD` for itself on startup, which is why a `cwd` alone is enough on Linux and macOS; `spawn`
 * does not, and neither does cmd.exe. So on Windows the `PWD` that Git's `sh.exe` exports for a
 * `just` recipe — `/c/Users/dev/Urbo`, the repo root in MSYS spelling — reaches every descendant
 * of `up.mjs`'s `pnpm install`, the twenty `openapi-generator-cli` runs behind its `prepare`
 * included. That CLI resolves `--openapitools ./openapitools-*.json` against `process.env.PWD`
 * ahead of its own working directory, so it looked for each config one directory too high, under
 * a path Windows reads as `C:\c\Users\...`. Finding no generators there it wrote an empty config
 * in their place, ignored the pinned generator version with it, forwarded the bare `generate` to
 * the jar, and left `just fresh` failing twenty times over on `Required option '-i' is missing`.
 */
export function spawnResolved(command, args, { spawnProcess = spawn, ...options } = {}) {
  const env = options.env ?? process.env;
  const resolved = resolveCommand(command, args, { env });
  return spawnProcess(resolved.command, resolved.args, {
    ...options,
    // Spelled upper case on purpose: Windows env keys are case-insensitive, and Node breaks the
    // tie between two spellings of one name by taking the lexicographically first, which `PWD`
    // always is.
    env: { ...env, PWD: resolve(options.cwd ?? process.cwd()) },
    windowsVerbatimArguments: resolved.windowsVerbatimArguments === true,
  });
}

/**
 * The PATH walk Windows does for itself: every directory in turn, and within each one every
 * `PATHEXT` extension in turn — so a `docker.cmd` earlier on PATH really does beat a `docker.exe`
 * later on it, and within one directory the `.exe` wins. The extension-less candidate that cmd
 * would also try is deliberately skipped: the `pnpm`/`just` sitting beside the `.cmd` is a bash
 * script, and nothing Win32 can execute.
 *
 * PATHEXT is spelled in upper case and the files themselves almost never are, so the extension is
 * lower-cased on the way in: it costs nothing on a case-insensitive filesystem and it keeps the
 * resolved path readable when it turns up in an error message.
 */
function findOnPath(command, env, fileExists) {
  const directories = split(valueOf(env, 'PATH'));
  const extensions = split(valueOf(env, 'PATHEXT') ?? DEFAULT_PATHEXT);

  for (const directory of directories) {
    for (const extension of extensions) {
      const candidate = win32.join(directory, `${command}${extension.toLowerCase()}`);
      if (fileExists(candidate)) {
        return candidate;
      }
    }
  }
  return null;
}

/**
 * `cmd.exe /d /s /c "<line>"`, the shape Node's own `shell: true` uses: `/s` strips exactly the
 * outer quote pair and takes the rest verbatim, so every token inside carries its own quotes and
 * survives its spaces. Quoting each token also leaves cmd.exe's metacharacters inert — `%VAR%`
 * being the exception, and no caller here passes one.
 */
function commandLine(executable, args) {
  return `"${[executable, ...args].map(quote).join(' ')}"`;
}

function quote(token) {
  // A run of backslashes only escapes the quote that follows it, so the run in front of a quote
  // has to be doubled — otherwise `C:\dir\` would close as `"C:\dir\"` and swallow its own quote.
  const escaped = String(token)
    .replace(/(\\*)"/g, '$1$1\\"')
    .replace(/(\\*)$/, '$1$1');
  return `"${escaped}"`;
}

/** Windows spells it `Path`, not `PATH` — and `ComSpec` in a third casing again. */
function valueOf(env, name) {
  const key = Object.keys(env).find((candidate) => candidate.toLowerCase() === name.toLowerCase());
  return key === undefined ? undefined : env[key];
}

function split(value) {
  return (value ?? '').split(win32.delimiter).filter((entry) => entry !== '');
}
